(async function () {
  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const allEls = () => {
    const out = []; const seen = new Set();
    const walk = (r) => r.querySelectorAll('*').forEach((e) => {
      out.push(e);
      if (e.shadowRoot && !seen.has(e.shadowRoot)) { seen.add(e.shadowRoot); walk(e.shadowRoot); }
    });
    walk(document); return out;
  };
  // RentSync FPN renders the full unit list under "Show All".
  for (const el of allEls()) {
    if (norm(el.textContent).toLowerCase() === 'show all') { try { el.click(); } catch (e) {} break; }
  }
  await new Promise((r) => setTimeout(r, 3000));
  // Each unit = <ul class="unit-card__column-list"> with data-column-field cells
  // (bed, bath, sqFt, rate, customField), nested inside <floorplan-navigator>'s shadow DOM.
  const cards = allEls().filter((e) => e.tagName === 'UL' && typeof e.className === 'string' && e.className.indexOf('unit-card__column-list') >= 0 && e.querySelector('[data-column-field]'));
  const lines = ['=== SIGNAL PER-UNIT LISTINGS (RentSync FPN nested shadow DOM) ==='];
  const seen = new Set();
  let n = 0;
  for (const card of cards) {
    const get = (f) => { const el = card.querySelector('[data-column-field="' + f + '"]'); return el ? norm(el.textContent) : ''; };
    const bed = get('bed'), bath = get('bath'), sqft = get('sqFt'), rate = get('rate'), cf = get('customField');
    if (!bed && !sqft && !rate) continue;
    const key = bed + '|' + bath + '|' + sqft + '|' + rate + '|' + cf;
    if (seen.has(key)) continue;
    seen.add(key);
    n++;
    lines.push('Unit ' + n + ' | ' + bed + ' | ' + bath + ' | ' + sqft + ' | ' + rate + (cf && cf !== '-' ? ' | ' + cf : ''));
  }
  lines.push('');
  lines.push('TOTAL UNITS EXTRACTED FROM FPN: ' + n);
  const pre = document.createElement('pre');
  pre.id = 'signal-units-dump';
  pre.style.cssText = 'display:block;white-space:pre-wrap;font-family:monospace;padding:20px;z-index:1;position:relative;';
  pre.textContent = lines.join('\n');
  document.body.appendChild(pre);
})();
